<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Testimonial; use Illuminate\Http\Request; class TestimonialController extends Controller { public function index(){return view('admin.testimonials.index',['items'=>Testimonial::latest()->get()]);} public function store(Request $r){$v=$r->validate(['name'=>'required|max:100','message'=>'required|max:1000']);Testimonial::create($v);return back()->with('success','Testimonial added.');} public function toggle(Testimonial $testimonial){$testimonial->update(['is_active'=>!$testimonial->is_active]);return back();} public function destroy(Testimonial $testimonial){$testimonial->delete();return back();} }
